const char *new_root_path = "/home/jail";
int result = chroot(new_root_path);

if (result == -1) {
    // Requires privileged access (EPERM if not root/CAP_SYS_CHROOT)
    // Also check for EACCES, EFAULT, or ENOTDIR
    return -1;
}

// Success: The effective root directory ('/') is now new_root_path.
// Note: chdir("/") is often called immediately after for cleanup.
// Current working directory remains unchanged until chdir().

// Example usage following chroot:
// chdir("/");
